  left outer join
  mst_exam_item as item on info->>''item_cd'' = (item.exam_item_cd || '''')  and item.is_del =''0''  and item.is_disp =''1'' 
	LEFT JOIN infection_order AS inf ON info ->> ''item_cd'':: text = inf.infection_cd 
	ORDER BY
infection_cd_order
	limit 100  ;
	
	
	' WHERE "sql_cd" = 48;

